select cron.schedule('research-history-self-heal','20 2 * * *',$$select net.http_post(url := (select decrypted_secret from vault.decrypted_secrets where name='project_url') || '/functions/v1/multi-year-history',headers := jsonb_build_object('Content-Type','application/json','x-monitor-secret',(select decrypted_secret from vault.decrypted_secrets where name='monitor_cron_secret')),body := '{"years":5}'::jsonb,timeout_milliseconds := 30000);$$);